script:
# The whole Connecticut General Statutes, one page per chapter. A section opens with <span class="catchln" id="sec_53-20">
# "Sec. 53-20. Cruelty to persons." and runs to the chapter's nav table. Its own paragraphs carry no class (or a form's);
# the source line is class source. History, annotations and cross-references are the editors' notes, not the law.
# (The first recipe read title 53 only and landed most sections as the bare catchline, 2026-10-06.)
import re, html
BASE = 'https://www.cga.ct.gov/current/pub/'
CATCH = re.compile(r'<span class="catchln" id="sec_([^"]+)">(.*?)</span>', re.S)
PARA = re.compile(r'<p(?:\s+class="([^"]*)")?[^>]*>(.*?)</p>', re.S)
NOTES = ('history', 'annotation', 'cross-ref', 'front-note', 'toc')
def plain(s):
    return re.sub(r'\s+', ' ', html.unescape(re.sub(r'<[^>]+>', ' ', s))).strip()
def page(url):
    kind, body = fetch(url)
    return body if isinstance(body, str) else body.decode('utf-8', 'ignore')
def sections():
    titles = list(dict.fromkeys(re.findall(r'title_[0-9a-z]+\.htm', page(BASE + 'titles.htm'))))
    log('titles: ' + str(len(titles)))
    for t in titles:
        try:
            chapters = list(dict.fromkeys(re.findall(r'chap_[0-9a-z]+\.htm', page(BASE + t))))
        except Exception as e:
            log('title failed ' + t + ' ' + repr(e)); continue
        for ch in chapters:
            try:
                body = page(BASE + ch)
            except Exception as e:
                log('chapter failed ' + ch + ' ' + repr(e)); continue
            hits = list(CATCH.finditer(body))
            for i, m in enumerate(hits):
                seg = body[m.start():hits[i + 1].start() if i + 1 < len(hits) else len(body)]
                seg = seg.split('<table class="nav_tbl"', 1)[0]
                lines = [plain(b) for cls, b in PARA.findall('<p>' + seg) if not (cls or '').lower().startswith(NOTES)]
                lines = [l for l in lines if l]
                catch = plain(m.group(2))
                heading = re.sub(r'^Secs?\.\s*\S+(?:\s+(?:to|and)\s+\S+)?\s*', '', catch).rstrip('.').strip()
                if lines:
                    yield {'id': m.group(1), 'heading': heading, 'text': '\n'.join(lines), 'url': BASE + ch + '#sec_' + m.group(1)}
